Future<void> uploadFoodDatabase() async {
  final FirebaseFirestore firestore = FirebaseFirestore.instance;
  final CollectionReference foodCollection = firestore.collection('foods');

  for (final food in foodData) {
    try {
      final docId = food['name']; // Using name as unique doc ID
      await foodCollection.doc(docId).set(food);
      print("✅ Uploaded: $docId");
    } catch (e) {
      print("❌ Error uploading ${food['name']}: $e");  
    }
  }

  print("🎉 All food items uploaded successfully.");
}
